# Helper for structured reading of values from a RustBuffer.
class RustBufferStream

  def initialize(rbuf)
    @rbuf = rbuf
    @offset = 0
  end

  def remaining
    @rbuf.len - @offset
  end

  def read(size)
    raise InternalError, 'read past end of rust buffer' if @offset + size > @rbuf.len

    data = @rbuf.data.get_bytes @offset, size

    @offset += size

    data
  end

  def readU8
    unpack_from 1, 'c'
  end

  def readU32
    unpack_from 4, 'L>'
  end

  def readF32
    unpack_from 4, 'g'
  end

  def readString
    size = unpack_from 4, 'l>'

    raise InternalError, 'Unexpected negative string length' if size.negative?

    read(size).force_encoding(Encoding::UTF_8)
  end

  

  

  # The Error type UniElidError

  def readTypeUniElidError
    variant = unpack_from 4, 'l>'
    
    if variant == 1
      return UniElidError::InvalidDimension.new(
        readString()
      )
    end
    if variant == 2
      return UniElidError::InvalidValue.new(
        readString()
      )
    end
    if variant == 3
      return UniElidError::InvalidEncoding.new(
        readString()
      )
    end
    if variant == 4
      return UniElidError::InvalidHeader.new(
        readString()
      )
    end
    if variant == 5
      return UniElidError::ProfileMismatch.new(
        readString()
      )
    end
    if variant == 6
      return UniElidError::TransformNotFound.new(
        readString()
      )
    end

    raise InternalError, 'Unexpected variant tag for TypeUniElidError'
  end
  

  
  
  # The Enum type UniProfile.

  def readTypeUniProfile
    variant = unpack_from 4, 'l>'
    
    if variant == 1
      return UniProfile::MINI128
    end
    if variant == 2
      return UniProfile::MORTON10X10
    end
    if variant == 3
      return UniProfile::HILBERT10X10
    end

    raise InternalError, 'Unexpected variant tag for TypeUniProfile'
  end

  

  # The Sequence<T> type for u8.

  def readSequenceu8
    count = unpack_from 4, 'l>'

    raise InternalError, 'Unexpected negative sequence length' if count.negative?

    items = []

    count.times do
