# Helper for structured writing of values into a RustBuffer.
class RustBufferBuilder
  def initialize
    @rust_buf = RustBuffer.alloc 16
    @rust_buf.len = 0
  end

  def finalize
    rbuf = @rust_buf

    @rust_buf = nil

    rbuf
  end

  def discard
    return if @rust_buf.nil?

    rbuf = finalize
    rbuf.free
  end

  def write(value)
    reserve(value.bytes.size) do
      @rust_buf.data.put_array_of_char @rust_buf.len, value.bytes
    end
  end

  def write_U8(v)
    v = ElidFfi::uniffi_in_range(v, "u8", 0, 2**8)
    pack_into(1, 'c', v)
  end

  def write_U32(v)
    v = ElidFfi::uniffi_in_range(v, "u32", 0, 2**32)
    pack_into(4, 'L>', v)
  end

  def write_F32(v)
    pack_into(4, 'g', v)
  end

  def write_String(v)
    v = ElidFfi::uniffi_utf8(v)
    pack_into 4, 'l>', v.bytes.size
    write v
  end

  

  # The Enum type UniProfile.

  def write_TypeUniProfile(v)
    pack_into(4, 'l>', v)
 end
   

  # The Sequence<T> type for u8.

  def write_Sequenceu8(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_U8(item)
    end
  end

  # The Sequence<T> type for f32.

  def write_Sequencef32(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_F32(item)
    end
  end

  # The Sequence<T> type for string.

  def write_Sequencestring(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_String(item)
    end
  end

  # The Sequence<T> type for Sequencef32.

  def write_SequenceSequencef32(items)
    pack_into(4, 'l>', items.size)

    items.each do |item|
      self.write_Sequencef32(item)
    end
  end

  

  private

  def reserve(num_bytes)
    if @rust_buf.len + num_bytes > @rust_buf.capacity
      @rust_buf = RustBuffer.reserve(@rust_buf, num_bytes)
    end

    yield

    @rust_buf.len += num_bytes
  end

  def pack_into(size, format, value)
    reserve(size) do
      @rust_buf.data.put_array_of_char @rust_buf.len, [value].pack(format).bytes
    end
  end
end

